{\n    background: #607d94; }\n  .btn-back .icon-arrow {\n    font-size: 12px;\n    margin-right: 10px;\n    transform: rotate(90deg);\n    color: inherit; }\n\n.icon-block {\n  position: absolute;\n  bottom: 6px;\n  right: 5px; }\n  @media (max-width: 600px) {\n    .icon-block {\n      margin-top: 1rem; } }\n\n.page-form {\n  position: relative;\n  margin: 1.5rem 1.5rem 0;\n  padding: 1.5rem 0.5rem;\n  background: #fff;\n  box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.14), 0 3px 1px -2px rgba(0, 0, 0, 0.2), 0 1px 5px 0 rgba(0, 0, 0, 0.12); }\n  .page-form .row {\n    margin-bottom: 0; }\n    .page-form .row .col {\n      padding: 0 1rem; }\n  .page-form .input-field {\n    font-size: 1.2rem; }\n    .page-form .input-field label {\n      left: 1rem;\n      font-size: 1.1rem;\n      color: #808080; }\n    .page-form .input-field input[type=text] {\n      height: 2.5rem;\n      line-height: 2.5rem;\n      border-color: #ccc;\n      font-size: 1.3rem;\n      color: #2c2c2c;\n      margin-bottom: 10px; }\n      .page-form .input-field input[type=text][readonly=\"readonly\"] {\n        border-bottom: 1px solid #ccc; }\n        .page-form .input-field input[type=text][readonly=\"readonly\"] + label {\n          color: #808080; }\n      .page-form .input-field input[type=text]:focus:not([readonly]) {\n        border-color: #549cba; }\n        .page-form .input-field input[type=text]:focus:not([readonly]) + label {\n          color: #549cba; }\n    .page-form .input-field ::-webkit-input-placeholder {\n      /* Chrome/Opera/Safari */\n      color: #2c2c2c; }\n    .page-form .input-field.input label {\n      top: 8px; }\n    .page-form .input-field .icon-calendar {\n      position: absolute;\n      right: 10px;\n      top: -1px;\n      font-size: 16px;\n      color: #4d6273; }\n  .page-form .dropdown-content {\n    margin-top: 5px; }\n  .page-form .dropdown-content li > a, .page-form .dropdown-content li > span {\n    font-size: 1.3rem;\n    color: #2c2c2c; }\n\n.table a {\n  color: #147ccc;\n  text-decoration: none; }\n  .table a:hover, .table a:focus, .table a:active {\n    text-decoration: none; }\n\n.table > thead > tr > th {\n  vertical-align: middle;\n  text-align: center;\n  background: #d1dae1;\n  border: 1px solid #ffffff;\n  border-top: 1px solid #d1dae1;\n  color: #314453;\n  font-weight: 500;\n  padding: 2px 5px;\n  border-radius: 0; }\n  .table > thead > tr > th:first-child {\n    border-left-color: #d1dae1 !important; }\n  .table > thead > tr > th:last-child {\n    border-right-color: #d1dae1 !important; }\n\n.table > tbody tr td {\n  border: 1px solid #d6d6d6;\n  color: #404040;\n  padding: 2px 5px;\n  background: #ededed; }\n\n.table > tbody tr:nth-child(odd) td {\n  background: #fff; }\n\n.table > tbody tr:hover td {\n  background: #fcf4df; }\n\n.table > tbody tr.total td {\n  background: #ffb391; }\n\n.table > tbody tr.highlight td {\n  background: #f7dbb6;\n  font-weight: bold; }\n\n.page-results {\n  margin: 1.5rem 1.5rem 0; }\n\n.table-title {\n  background: #8aa4b8;\n  padding: 4px 15px;\n  color: #fff;\n  text-transform: uppercase; }\n\n.panel-heading {\n  background: #4C6375;\n  border-radius: 0;\n  padding: 0; }\n  .panel-heading .panel-title {\n    color: #fff;\n    padding: 5px 15px;\n    font-size: 13px; }\n    .panel-heading .panel-title .icon-arrow {\n      margin: 0;\n      font-size: 13px;\n      transform: rotate(-90deg);\n      transition: 0.3s ease all; }\n    .panel-heading .panel-title:hover, .panel-heading .panel-title:active, .panel-heading .panel-title:focus {\n      color: #fff; }\n  .panel-heading + .panel-collapse > .panel-body {\n    border-top: none !important; }\n  .panel-heading.active .panel-title .icon-arrow {\n    transform: rotate(0); }\n\n.icon-block {\n  bottom: 0; }\n\n.table > thead > tr > th {\n  background: #4C6375;\n  color: #fff; }\n\n\n\n// WEBPACK FOOTER //\n// webpack:///www/css/source/pages/report/settledmatchcount.scss"],"sourceRoot":""}
